css:
.d-word-frequency-counter{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-word-frequency-counter *,.d-word-frequency-counter *::before,.d-word-frequency-counter *::after{box-sizing:border-box}
.d-word-frequency-counter [hidden]{display:none!important}
.d-word-frequency-counter .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-word-frequency-counter .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-word-frequency-counter label{display:block;margin:8px 0}
.d-word-frequency-counter input,.d-word-frequency-counter select,.d-word-frequency-counter textarea,.d-word-frequency-counter button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-word-frequency-counter input:not([type=checkbox]):not([type=radio]),.d-word-frequency-counter select,.d-word-frequency-counter textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-word-frequency-counter button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-word-frequency-counter button:disabled{opacity:.5;cursor:default}
.d-word-frequency-counter :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-word-frequency-counter [aria-invalid=true]{border-color:var(--warn)!important}
.d-word-frequency-counter .d-scroll{max-width:100%;overflow:auto}
.d-word-frequency-counter table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-word-frequency-counter th,.d-word-frequency-counter td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-word-frequency-counter caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-word-frequency-counter progress{width:100%;accent-color:var(--ink)}
.d-word-frequency-counter pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-word-frequency-counter h3,.d-word-frequency-counter p{margin:8px 0}
.d-word-frequency-counter [aria-pressed=true],.d-word-frequency-counter [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-word-frequency-counter .d-grow{flex:1;min-width:100px}
.d-word-frequency-counter summary{cursor:pointer;padding:6px 0}
.d-word-frequency-counter ul,.d-word-frequency-counter ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-count]').onclick=()=>{const text=q('[data-input]').value,words=text.toLocaleLowerCase().match(/[\p{L}\p{N}]+/gu)||[],counts=new Map();words.forEach(word=>counts.set(word,(counts.get(word)||0)+1));const sorted=[...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));q('[data-result]').replaceChildren(...sorted.slice(0,20).map(([word,count])=>{const li=document.createElement('li');li.textContent=word+'：'+count;return li;}));say('非空白字符 '+[...text.replace(/\s/g,'')].length+'；词段 '+words.length+'；中文连续文字视为一个词段');};})(root, q, qa, say);
}
